#ifndef __MAHJONGJAPAN_GAMETEXT_H__
#define __MAHJONGJAPAN_GAMETEXT_H__

// The few strings of the exe that the player sees (the map's stage names) are read from the player's own
// MahjongEscapeAJ.exe at start-up, by address: no game text is in the repository. The strings of Resource.dll are
// read from it as the original reads them (PeResources.h).
//
// - GameTextTable.inc (generated by games/mahjongjapan/tools/make_gametext.py from the GT() and GTA() of src/) lists
//   each string's address in the game image, its length and a hash: no text.
// - LoadGameTexts() reads the exe from the game folder, takes each string at its address and checks length and hash.
//   A string that does not match (another version of the exe) stays empty and is logged.
// - Code names a string by its address in the original: GT(0x00525160); a table of addresses marks each with GTA().

#include <cstdint>
#include <string>

namespace mahjongjapan
{

// Reads the strings from theFolder's MahjongEscapeAJ.exe. Returns false when the exe is missing or no string matched.
bool LoadGameTexts(const std::string& theFolder);
// The string the original keeps at theVA; "" for an address that is not in the table
const char* GameText(uint32_t theVA);

} // namespace mahjongjapan

#define GT(theVA) (::mahjongjapan::GameText(theVA))
#define GTA(theVA) (theVA)

#endif
